#!/bin/bash -l
# Generated by scripts/generate_encoder_followups_slurm.py; no original run is overwritten.
#SBATCH --job-name=encoder-target-controls-s42
#SBATCH --output=/scratch/users/%u/%x-%A_%a.out
#SBATCH --error=/scratch/users/%u/%x-%A_%a.err
#SBATCH --array=0-1
#SBATCH --partition=biomed_a100_gpu
#SBATCH --gres=gpu:1
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --mem=64G
#SBATCH --cpus-per-task=8
#SBATCH --time=48:00:00
#SBATCH --constraint=a100_80g

set -euo pipefail
REPO="${ENCODER_REPO:-${SLURM_SUBMIT_DIR:-$PWD}}"
CONDA_ENV_NAME=multiview-env
PYTHON="${ENCODER_PYTHON:-${HOME}/.conda/envs/${CONDA_ENV_NAME}/bin/python}"
RUNS="${ENCODER_RUNS:-$REPO/results/encoder_ablations_slurm_bio/runs}"
OUTPUT="${ENCODER_FOLLOWUPS:-$REPO/results/encoder_followups_slurm_bio}"
TASK_ID="${SLURM_ARRAY_TASK_ID:-${ENCODER_TASK_ID:-0}}"
if [[ ! "$TASK_ID" =~ ^[0-1]$ ]]; then echo "Invalid task index: $TASK_ID" >&2; exit 2; fi
NAMES=(t1 flair)
NAME="${NAMES[$TASK_ID]}"
STAMP="${SLURM_ARRAY_JOB_ID:-${SLURM_JOB_ID:-preview}}_${TASK_ID}"
REFERENCE="${ENCODER_REFERENCE_RUN:-$RUNS/conv_mlp_s42}"
COMMAND=("$PYTHON" -m training.encoder_target_control --run-dir "$REFERENCE" --out-dir "$OUTPUT/supervised/${NAME}_${STAMP}" --view "$NAME" --device cuda --steps 2000 --batch-size 8 --width 24 --grid 8 --test-samples 400 --seed 42)
if [[ "$#" -gt 1 ]]; then echo "Usage: $0 [--dry-run]" >&2; exit 2; fi
case "${1:-}" in
  --dry-run) printf '%q ' "${COMMAND[@]}"; printf '\n'; exit 0 ;;
  "") ;;
  *) echo "Usage: $0 [--dry-run]" >&2; exit 2 ;;
esac
if [[ -z "${SLURM_JOB_ID:-}" ]]; then echo "Submit with sbatch; use --dry-run for preview." >&2; exit 2; fi
cd "$REPO"
test -f eval/encoder_spatial_target_audit.py && test -f training/encoder_target_control.py
module load anaconda3/2022.10-gcc-13.2.0
if [[ ! -x "$PYTHON" ]]; then echo "Python missing: $PYTHON" >&2; exit 1; fi
export PYTHONPATH="$REPO" PYTHONNOUSERSITE=1 PYTHONUNBUFFERED=1 CUBLAS_WORKSPACE_CONFIG=:4096:8
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1
echo "Node: $(hostname) Job: $SLURM_JOB_ID Task: $TASK_ID ($NAME)"
"$PYTHON" -c 'import torch; print(torch.__version__); assert torch.cuda.is_available(), '"'"'No usable CUDA device'"'"''
exec "${COMMAND[@]}"
